def max_value_on_paths(N: int, grid_values: list) -> int:
    # Create a grid of zeros, 1-indexed
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    # DP: dp[i1][i2] for current step k
    from math import inf
    neg_inf = -10**18
    dp_prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    # At step k = 2, both at (1,1)
    dp_prev[1][1] = grid[1][1]

    # Iterate over sum of coordinates k from 3 to 2N
    for k in range(3, 2 * N + 1):
        dp_cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 bounds: they must be between max(1, k-N) and min(N, k-1)
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                # Calculate best previous step
                best = neg_inf
                # Moves: each person could come from left (i same, j-1) or up (i-1, j same)
                for di1 in (0, -1):
                    pi1 = i1 + di1
                    pj1 = j1 + (1 if di1 == 0 else 0)
                    if pi1 < 1 or pi1 > N or pj1 < 1 or pj1 > N:
                        continue
                    for di2 in (0, -1):
                        pi2 = i2 + di2
                        pj2 = j2 + (1 if di2 == 0 else 0)
                        if pi2 < 1 or pi2 > N or pj2 < 1 or pj2 > N:
                            continue
                        if dp_prev[pi1][pi2] > best:
                            best = dp_prev[pi1][pi2]
                if best == neg_inf:
                    continue
                # Add current cells' values
                val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                dp_cur[i1][i2] = best + val
        dp_prev = dp_cur

    # Result at bottom-right
    return dp_prev[N][N] if dp_prev[N][N] != neg_inf else 0

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check that all 26 uppercase alphabet letters are represented in the mapping
    if len(mapping) != 26:
        return "Failed"

    # Verify that every character in the message can be decoded
    for ch in message:
        if ch not in mapping:
            return "Failed"

    # Perform the decoding
    decoded_chars = [mapping[ch] for ch in message]
    return "".join(decoded_chars)

def minimum_students_to_leave(heights):
    """Calculate the minimum number of students that need to leave to form a
    choir formation. A choir formation is a bitonic sequence (strictly
    increasing then strictly decreasing). The function returns the smallest
    number of students that must be removed to achieve such a formation.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list of integers")
    if any(not isinstance(h, int) for h in heights):
        raise ValueError("all elements in heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Maximize bitonic length (increase + decrease - 1 for the peak counted twice)
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")
    # Validate each entry
    for idx, item in enumerate(student_scores):
        if not (isinstance(item, tuple) and len(item) == 3):
            raise ValueError(f"Item at index {idx} is not a tuple of length 3")
        sn, ts, cs = item
        if not (isinstance(sn, int) and isinstance(ts, int) and isinstance(cs, int)):
            raise ValueError(f"Item at index {idx} contains non-integer values")
    # Sorting key: total score descending, Chinese score descending, student number ascending
    return sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
